module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    reg [2:0] q;

    // Single flip-flop behavior: load r_in when L is high, otherwise shift/rotate
    always @(posedge clk) begin
        if (L) begin
            // When L is asserted, load the input r_in
            q <= {q_in, q_in, r_in};
        end else begin
            // When L is de-asserted, perform the shift/rotate operation
            // The new value is formed by: XOR of current Q[1] and Q[2], followed by Q[0], then Q[2]
            // This matches the behavior described in the specification for a single bit
            q <= {q[1] ^ q[2], q[0], q[2]};
        end
    end

    assign Q = q[0];

endmodule

