module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

    // State encoding: 2 bits for 4 states (A, B, C, D)
    typedef enum logic [1:0] {
        S_A = 2'b00,
        S_B = 2'b01,
        S_C = 2'b10,
        S_D = 2'b11
    } state_t;

    state_t state, next_state;

    // State register with synchronous active-high reset
    always_ff @(posedge clk) begin
        if (reset)
            state <= S_A;
        else
            state <= next_state;
    end

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            S_A: begin
                if (in)
                    next_state = S_B;
                else
                    next_state = S_A;
            end
            S_B: begin
                if (in)
                    next_state = S_B;
                else
                    next_state = S_C;
            end
            S_C: begin
                if (in)
                    next_state = S_D;
                else
                    next_state = S_A;
            end
            S_D: begin
                if (in)
                    next_state = S_B;
                else
                    next_state = S_C;
            end
            default: next_state = S_A; // Fallback
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    assign out = (state == S_D) ? 1'b1 : 1'b0;

endmodule

