module TopModule (
    input  clk,
    input  reset,
    input  data,
    output reg start_shifting
);

    // State encoding: 0=S0, 1=S1, 2=S2, 3=S3
    reg [1:0] state;
    reg [1:0] next_state;

    // State transition logic (combinational)
    always @(*) begin
        case (state)
            2'd0: begin // S0: Waiting for first '1'
                if (data == 1'b1)
                    next_state = 2'd1;
                else
                    next_state = 2'd0;
            end
            2'd1: begin // S1: Have seen first '1', waiting for second '1'
                if (data == 1'b1)
                    next_state = 2'd2;
                else if (data == 1'b0)
                    next_state = 2'd0; // Reset on '0'
                else
                    next_state = 2'd0;
            end
            2'd2: begin // S2: Have seen '11', waiting for '0'
                if (data == 1'b0)
                    next_state = 2'd3;
                else if (data == 1'b1)
                    next_state = 2'd2; // Stay in S2 if another '1' comes
                else
                    next_state = 2'd0;
            end
            2'd3: begin // S3: Have seen '110', waiting for final '1'
                if (data == 1'b1)
                    next_state = 2'd0; // Sequence found, reset to S0 (will set start_shifting)
                else if (data == 1'b0)
                    next_state = 2'd0;
                else
                    next_state = 2'd0;
            end
            default: next_state = 2'd0;
        endcase
    end

    // State update (sequential, positive edge triggered)
    always @(posedge clk) begin
        if (reset)
            state <= 2'd0;
        else
            state <= next_state;
    end

    // Output logic: set start_shifting when sequence 1101 is detected
    // The sequence is detected when we transition from S3 to S0 on data==1
    always @(posedge clk) begin
        if (reset)
            start_shifting <= 1'b0;
        else if (state == 2'd3 && data == 1'b1)
            start_shifting <= 1'b1;
        // start_shifting stays 1 forever once set (until reset)
    end

endmodule

