            end
            3'b100: begin
                if (x)
                    y = 3'b100;
                else
                    y = 3'b011;
            end
            default: y = 3'b000; // Should never happen
        endcase
    end

    // State update (sequential, positive edge triggered)
    always @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= y; // y is updated via the always @(*) block in simulation,
                    // but in synthesis the MUX/FFs capture the next state.
                    // The assignment below captures the intended next state.
                    // Note: The 'y' variable is updated on the clock edge
                    // based on the next state computed above.
        // The actual register update is implicitly handled by the
        // non-blocking assignment in the sequential block below.
    end

    // Proper sequential update using non-blocking assignment
    always @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= y; // Placeholder, will be overridden by the intent below.
    end

    // Redefining the state update to correctly reflect the FSM transition
    always @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            case (y)
                3'b000: y <= x ? 3'b001 : 3'b000;
                3'b001: y <= x ? 3'b100 : 3'b001;
                3'b010: y <= x ? 3'b001 : 3'b010;
                3'b011: y <= x ? 3'b010 : 3'b001;
                3'b100: y <= x ? 3'b100 : 3'b011;
                default: y <= 3'b000;
            endcase
    end

    // Output logic (Moore machine: output depends only on state)
    assign z = (y == 3'b011) || (y == 3'b100) ? 1'b1 : 1'b0;

