module TopModule (
    input  [3:0] x,
    output       f
);

    // Internal signals for K-map variables
    // x[3] is the most significant bit, x[0] is the least significant
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // Derived signals for K-map rows and columns
    // Row 0: x3=0, x2=0 -> x3' & x2'
    // Row 1: x3=0, x2=1 -> x3' & x2
    // Row 2: x3=1, x2=1 -> x3 & x2
    // Row 3: x3=1, x2=0 -> x3 & x2'
    wire row0 = ~x3 & ~x2; // 00
    wire row1 = ~x3 &  x2; // 01
    wire row2 =  x3 &  x2; // 11
    wire row3 =  x3 & ~x2; // 10

    // Column 0: x1=0, x0=0 -> x1' & x0'
    // Column 1: x1=0, x0=1 -> x1' & x0
    // Column 2: x1=1, x0=1 -> x1 & x0
    // Column 3: x1=1, x0=0 -> x1 & x0'
    wire col0 = ~x1 & ~x0; // 00
    wire col1 = ~x1 &  x0; // 01
    wire col2 =  x1 &  x0; // 11
    wire col3 =  x1 & ~x0; // 10

    // F is implemented by grouping the 1s and don't-cares from the K-map.
    // The following expression covers all 1s with minimal logic using
    // don't-care conditions to simplify the circuit.
    //
    // K-map analysis:
    //   x[1]x[2]
    // x[3]x[4]  00 01 11 10
    //   00 | d  0  d  d |
    //   01 | 0  d  1  0 |
    //   11 | 1  1  d  d |
    //   10 | 1  1  0  d |
    //
    // Essential prime implicants and groupings:
    // 1) Group of four: row2 (11) and row3 (10) for col2 (11) and col3 (10) -> x3 & x1
    //    Covers: (11,11), (11,10), (10,11), (10,10) -> all yield 1 or d.
    // 2) Group of four: col2 (11) and col3 (10) for row1 (01) and row2 (11) -> x2 & x0
    //    Covers: (01,11), (01,10), (11,11), (11,10) -> all yield 1 or d.
    // 3) Single 1 at (01,00) covered by row1 & col0 -> ~x3 & x2 & ~x1 & ~x0
    //    However, this 1 is also adjacent to don't-cares and can be absorbed
    //    by the larger groups if we choose, but to guarantee exact functionality
    //    we include the minimal essential term.
    //
    // Final simplified F:
    //   F = (x3 & x1) | (x2 & x0) | (~x3 & x2 & ~x1 & ~x0)
    //
    // Note: The term (~x3 & x2 & ~x1 & ~x0) can be expanded or factored,
    // but this form directly maps to the K-map ones and required don't-cares.
    assign f = (x3 & x1) | (x2 & x0) | (~x3 & x2 & ~x1 & ~x0);

endmodule

