module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [7:0] in,
    output logic [23:0] out_bytes,
    output logic done
);

    // State encoding
    typedef enum logic [2:0] {
        IDLE      = 3'b000,
        GOT_1     = 3'b001,
        GOT_2     = 3'b010,
        GOT_3     = 3'b011,
        DONE      = 3'b100
    } state_t;

    // Sequential logic: state and data registers
    // Fixed: Added declarations for 'state' and 'cnt'
    state_t state;
    logic [1:0] cnt;
    logic [23:0] out_bytes_int; // Internal register for output to avoid combinational loops if needed, 
                                 // but out_bytes can drive directly if assignments are sequential.

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            cnt       <= 2'b00;
            out_bytes <= 24'h0;
            done      <= 1'b0;
        end else begin
            // Default: done is cleared every cycle unless we are in the cycle after GOT_3
            done <= 1'b0;

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        state     <= GOT_1;
                        cnt       <= 2'b01;   // we have byte 1
                        out_bytes <= {24{1'b0}};
                        // Load first byte into out_bytes[23:16]
                        out_bytes[23:16] <= in;
                    end
                    // else stay in IDLE, out_bytes and done unchanged (x or previous)
                end

                GOT_1: begin
                    // Expect byte 2
                    // If in[3] is 1, a new message starts immediately, reset to GOT_1
                    if (in[3]) begin
                        // New message starts; reset to GOT_1
                        cnt       <= 2'b01;
                        out_bytes[23:16] <= in;
                        // State stays GOT_1 effectively, but we update cnt and byte
                    end else begin
                        cnt       <= 2'b10;   // we have byte 2
                        out_bytes[15:8]  <= in;
                        state         <= GOT_2; // Transition to GOT_2
                    end
                end

                GOT_2: begin
                    // Expect byte 3
                    // If in[3] is 1, a new message starts immediately, treat as byte 1
                    if (in[3]) begin
                        // New message starts; treat as byte 1
                        cnt       <= 2'b01;
                        out_bytes[23:16] <= in;
                        state     <= GOT_1; // Stay in GOT_1 chain
                    end else begin
                        cnt       <= 2'b11;   // we have byte 3
                        out_bytes[7:0]   <= in;
                        state           <= DONE; // Transition to DONE
                    end
                end

                GOT_3: begin
                    // This state handles the assertion of 'done' in the cycle 
                    // immediately after the third byte was latched.
                    done <= 1'b1;
                    // out_bytes already holds the 3 bytes from GOT_2 logic
                    // Transition back to IDLE next cycle
                    state <= IDLE;
                end

                DONE: begin
                    // done is asserted in this cycle; out_bytes is valid
                    // Immediately go back to IDLE for the next message
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

