assign next_S = (~d & state[0]) |                   // S -> S
                (~d & state[1]) |                   // S1 -> S
                (~d & state[3]) |                   // S110 -> S
                (ack & state[9]);                   // Wait -> S

// S1 next-state: from S (d=1), from S1 (d=1)
assign next_S1 = (d & state[0]) | (d & state[1]);

// S11 next-state: from S11 (d=1)
assign next_S11 = (d & state[2]);

// S110 next-state: from S11 (d=0)
assign next_S110 = (~d & state[2]);

// B0 next-state: from S110 (d=1)
assign next_B0 = (d & state[3]);

// B1 next-state: always from B0
assign next_B1 = state[4];   // B0 -> B1

// B2 next-state: always from B1
assign next_B2 = state[5];   // B1 -> B2

// B3 next-state: always from B2
assign next_B3 = state[6];   // B2 -> B3

