                    (~done_counting & state[8]); // Count -> Count / Wait -> Count (if done_counting=0, but Wait goes to S when ack=1; here we just assert next_Count when in B3 or Count)

// Wait next-state: from Count if done_counting=1, stays in Wait if ack=0
assign next_Wait = (~done_counting & state[8]) | 
                   (~ack & state[9]);      // Wait -> Wait if ack=0

