module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // FSM state encoding
    parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;

    // State and shift register for x pattern detection
    reg [1:0] state;
    reg [2:0] x_shift;

    // Outputs
    assign f = (state == B);
    assign g = (state == D);

    // Synchronous reset (active low)
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state     <= A;
            x_shift   <= 3'b000;
        end else begin
            // State transition logic
            case (state)
                A: begin
                    state <= B;
                end
                B: begin
                    // Detect x pattern: 1, 0, 1
                    x_shift <= {x_shift[1:0], x};
                    if (x_shift == 3'b101)
                        state <= C;
                    else
                        state <= B;
                end
                C: begin
                    // Monitor y within 2 clock cycles
                    if (y == 1'b1)
                        state <= D;
                    else
                        state <= C; // Stay in C, re-evaluate next cycle
                end
                D: begin
                    // Maintain state until reset
                    state <= D;
                end
                default: state <= A;
            endcase
        end
    end

endmodule

