module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    parameter S_WALK = 2'b00;
    parameter S_FALL = 2'b01;
    parameter S_DIG  = 2'b10;
    parameter S_SPLAT = 2'b11;

    // Internal state and next state logic
    reg [1:0] state, next_state;

    // Counters for fall timer and dig progress
    reg [4:0] fall_counter, next_fall_counter;
    reg [4:0] dig_counter, next_dig_counter;

    // Direction register: stores walking direction during/after fall/dig
    reg dir, next_dir;

    // Output assignments (Moore machine - outputs depend only on state)
    assign walk_left  = (state == S_WALK) && (dir == 1'b0);  // walk_left=1 when walking left
    assign walk_right = (state == S_WALK) && (dir == 1'b1); // walk_right=1 when walking right
    assign aaah       = (state == S_FALL);
    assign digging    = (state == S_DIG);

    // State register (positive edge triggered, async active high reset)
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_WALK;
            dir   <= 1'b0; // default walk left
            fall_counter <= 5'd0;
            dig_counter  <= 5'd0;
        end else begin
            state <= next_state;
            dir   <= next_dir;
            fall_counter <= next_fall_counter;
            dig_counter  <= next_dig_counter;
        end
    end

    // Next state logic (combinational)
    always @(*) begin
        // Default assignments: keep current state/values unless transition
        next_state = state;
        next_dir   = dir;
        next_fall_counter = fall_counter;
        next_dig_counter  = dig_counter;

        case (state)
            S_WALK: begin
                // Priority 1: Fall (ground=0) - takes precedence over everything
                if (ground == 1'b0) begin
                    next_state = S_FALL;
                    // Start fall counter; dir retains its current value below
                end
                // Priority 2: Dig (ground=1 and dig=1)
                else if (ground == 1'b1 && dig == 1'b1) begin
                    next_state = S_DIG;
                    next_dig_counter = 5'd1;
                end
                // Priority 3: Switch direction (bumped on one or both sides)
                else if ((bump_left == 1'b1) || (bump_right == 1'b1)) begin
                    // If bumped left -> walk right; bumped right -> walk left; both -> toggle
                    if (bump_left == 1'b1 && bump_right == 1'b1) begin
                        next_dir <= ~dir; // toggle direction
                    end else if (bump_left == 1'b1) begin
                        next_dir <= 1'b1; // walk right
                    end else if (bump_right == 1'b1) begin
                        next_dir <= 1'b0; // walk left
                    end
                end
                // If no conditions met, stay in S_WALK with dir unchanged (defaults above)
            end

            S_FALL: begin
                // Timer increments every cycle falling (as long as still falling)
                if (fall_counter < 5'd20) begin
                    next_fall_counter = fall_counter + 5'd1;
                end

                // Check for ground reappearance
                if (ground == 1'b1) begin
                    // Splatter if fell > 20 cycles
                    if (fall_counter > 5'd20) begin
                        next_state = S_SPLAT;
                    end else begin
                        // Resume walking in same direction (dir already holds the direction)
                        next_state = S_WALK;
                        // dir retains its current value (next_dir = dir default)
                    end
                end
                // If still falling, being bumped does nothing (spec)
                // being told to dig while falling is ignored (spec)
            end

            S_DIG: begin
                // If ground disappears (ground=0), stop digging and fall
                if (ground == 1'b0) begin
                    next_state = S_FALL;
                    next_fall_counter = 5'd1;
                    // dir remains as it was during dig (walking direction)
                end
                // If still on ground, check if dig command is released
                else if (dig == 1'b0) begin
                    // Stop digging, resume walking in same direction
                    next_state = S_WALK;
                    // dir retains its current value
                end
                // else: ground==1 & dig==1, stay in S_DIG (implicit by not changing next_state)
            end

            S_SPLAT: begin
                // Forever stuck in splat until reset
                // State stays S_SPLAT; all outputs 0 already by default or below.
            end
        endcase
    end

endmodule
